125	ostream& operator << (ostream& out, rule rule) {
126		//规则以“左部::=右部1|右部2|...”的形式输出
127		out << rule.left << "::=";
128		for (unsigned int i = 0; i < rule.right.size(); i++) {
129			if (i > 0) {
130				out << "|";
131			}
132			out << rule.right[i];
133		}
134		return out;
135	}
136	void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
137		//各条文法规则之间以空白分隔，每条规则形如“左部::=右部1|右部2|...”
138		stringstream ss(text);
139		string item;
140		while (ss >> item) {
141			string::size_type pos = item.find("::=");
142			if (pos == string::npos || pos == 0) {
143				continue;//不是一条合法的产生式，直接忽略
144			}
145			char left = item[0];
146			string rights = item.substr(pos + 3);
147	
148			//右部按“|”切分成若干个候选式
149			vector<string> parts;
150			string part = "";
151			for (unsigned int i = 0; i < rights.length(); i++) {
152				if (rights[i] == '|') {
153					parts.push_back(part);
154					part = "";
155				}
156				else {
157					part += rights[i];
158				}
159			}
160			parts.push_back(part);
161	
162			//同一个非终结符的产生式可能分开书写，合并到同一条规则中
163			int at = -1;
164			for (unsigned int i = 0; i < rules.size(); i++) {
165				if (rules[i].left == left) {
166					at = (int)i;
167					break;
168				}
169			}
170			if (at < 0) {
171				rule new_rule;
172				new_rule.left = left;
173				rules.push_back(new_rule);
174				at = (int)rules.size() - 1;
175			}
176			for (unsigned int i = 0; i < parts.size(); i++) {
177				if (!parts[i].empty()) {
178					rules[at].right.push_back(parts[i]);
179				}
180			}
181			//出现在规则左部的一定是非终结符
182			non_terminal.insert(left);
183		}
184	
185		//所有规则左部都收集完毕之后，再回头区分右部中的终结符和非终结符
186		for (unsigned int i = 0; i < rules.size(); i++) {
187			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
188				const string& part = rules[i].right[j];
189				right_parts.insert(part);
190				for (unsigned int k = 0; k < part.length(); k++) {
191					char c = part[k];
192					if (c == '@') {
193						continue;//“@”代表空串ε，既不是终结符也不是非终结符
194					}
195					if (non_terminal.count(c) > 0) {
196						continue;
197					}
198					if (isupper((unsigned char)c)) {
199						non_terminal.insert(c);//大写字母一律看作非终结符
200					}
201					else {
202						terminal.insert(c);
203					}
204				}
205			}
206		}
207	}
