72	static void test_first() {
73		grammar g(G3);
74		expect_eq(to_s(findFirst("aH", g.rules)), "First(aH)={a}", "G3 First(aH)");
75		expect_eq(to_s(findFirst("aMd", g.rules)), "First(aMd)={a}", "G3 First(aMd)");
