//求非终结符non_terminal的Follow集，visiting记录当前正在求解的非终结符，防止文法中的递归导致死循环
static set<char> followOf(const char non_terminal, const vector<rule>& rules, set<char>& visiting) {
	set<char> result;
	result.insert('#');//约定输入串结束符“#”总是可以出现在非终结符的后面
	visiting.insert(non_terminal);
	for (unsigned int i = 0; i < rules.size(); i++) {
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			const string& part = rules[i].right[j];
			for (unsigned int k = 0; k < part.length(); k++) {
				if (part[k] != non_terminal) {
					continue;//该候选式的这个位置上不是要找的非终结符
				}
				//紧跟其后的符号串决定它的Follow集，空后缀的First集约定为“@”
				set<char> visiting_first;
				set<char> first = firstOf(part.substr(k + 1), rules, visiting_first);
				bool has_epsilon = false;
				for (set<char>::iterator it = first.begin(); it != first.end(); it++) {
					if (*it == '@') {
						has_epsilon = true;//后缀能推出空串，还要看规则左部的Follow集
					}
					else {
						result.insert(*it);
					}
				}
				if (!has_epsilon) {
					continue;//后缀推不出空串，该处出现不再有别的贡献
				}
				//位于规则右部末尾（或其后缀能推出空串）时，规则左部的Follow集并入
				if (visiting.count(rules[i].left) > 0) {
					continue;//该非终结符正处在求解过程中，再递归下去就会陷入死循环
				}
				set<char> sub = followOf(rules[i].left, rules, visiting);
				for (set<char>::iterator it = sub.begin(); it != sub.end(); it++) {
					result.insert(*it);
				}
			}
		}
	}
	visiting.erase(non_terminal);
	return result;
}
F_set findFollow(const char non_terminal, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = false;
	f_set.left = non_terminal;
