	//逐个求出各非终结符的Follow集，输出顺序与前面提取非终结符时一致
	vector<F_set> f_sets;
	cout << "各非终结符的Follow集：" << endl;
	for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
		F_set f_set = findFollow(*it, rules);
		cout << "    " << f_set << endl;
		f_sets.push_back(f_set);
	}
	cout << endl;
	return f_sets;
}
//在表头数组中查找某个符号所在的下标，找不到时返回-1
static int index_of(const vector<char>& head, const char c) {
	for (unsigned int i = 0; i < head.size(); i++) {
		if (head[i] == c) {
			return (int)i;
		}
	}
	return -1;
}
LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
	LL_1_table table;
	//行表头：按规则出现的先后顺序排列非终结符，这样row[0]就是文法的开始符号
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (index_of(table.row, rules[i].left) < 0) {
			table.row.push_back(rules[i].left);
		}
	}
	//只出现在右部、没有产生式的非终结符补在后面，保证行表头覆盖全部非终结符
	for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
		if (index_of(table.row, *it) < 0) {
			table.row.push_back(*it);
		}
	}
	//列表头：全部终结符依次排列，末尾补上输入串结束符“#”
	for (set<char>::iterator it = terminal.begin(); it != terminal.end(); it++) {
		table.col.push_back(*it);
	}
	table.col.push_back('#');
	//先把每一个单元格都填成右部为空的规则，空单元格表示分析到此处即出错
	rule empty_rule;
	empty_rule.left = ' ';
	table.rules.assign(table.row.size() * table.col.size(), empty_rule);

	//逐条候选式填表：First集中的终结符直接决定列，含“@”时改用左部的Follow集
	for (unsigned int i = 0; i < rules.size(); i++) {
		int r = index_of(table.row, rules[i].left);
		if (r < 0) {
			continue;
		}
		F_set follow = findFollow(rules[i].left, rules);
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			//单元格里存放的是“左部::=本候选式”这一条产生式
			rule cell;
			cell.left = rules[i].left;
			cell.right.push_back(rules[i].right[j]);
			F_set first = findFirst(rules[i].right[j], rules);
			set<char> cols;
			for (set<char>::iterator it = first.right.begin(); it != first.right.end(); it++) {
				if (*it != '@') {
					cols.insert(*it);//终结符a属于First集，则[左部,a]处填该候选式
					continue;
				}
				//候选式能推出空串，则Follow集中的每一个符号所在列都填该候选式
				for (set<char>::iterator ft = follow.right.begin(); ft != follow.right.end(); ft++) {
					cols.insert(*ft);
				}
			}
			for (set<char>::iterator it = cols.begin(); it != cols.end(); it++) {
				int c = index_of(table.col, *it);
				if (c < 0) {
					continue;//该符号不是文法的终结符，分析表中没有对应的列
				}
				if (!table.rules[r * table.col.size() + c].right.empty()) {
					continue;//单元格已被占用（文法不满足LL(1)条件），保留先填入的产生式
				}
				table.rules[r * table.col.size() + c] = cell;
			}
		}
	}
	return table;
}
ostream& operator << (ostream& out, LL_1_table table) {
	//表格左上角空出一格放行表头，其余每一列对应一个终结符或输入串结束符
	out << endl << "LL（1）分析表如下：" << endl;
	out << left << setw(8) << " ";
	for (unsigned int j = 0; j < table.col.size(); j++) {
		out << setw(12) << table.col[j];
	}
	out << endl;
	for (unsigned int i = 0; i < table.row.size(); i++) {
		out << setw(8) << table.row[i];
		for (unsigned int j = 0; j < table.col.size(); j++) {
			rule cell = table.rules[i * table.col.size() + j];
			if (cell.right.empty()) {
				out << setw(12) << " ";//空单元格代表分析到此处即出错
				continue;
			}
			//借助字符串流把产生式整体作为一个单元格输出，宽度才不会被打乱
			ostringstream cell_text;
			cell_text << cell;
			out << setw(12) << cell_text.str();
		}
		out << endl;
	}
	out << right;//恢复默认的对齐方式，避免影响后面的输出
	return out;
}
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
	//分析栈自栈底向栈顶输出：出栈先得到栈顶符号，收集完再整体反转
	string analysis = "";
	while (!analysis_s.empty()) {
		analysis += analysis_s.top();
		analysis_s.pop();
	}
	reverse(analysis.begin(), analysis.end());
	//输入栈的栈顶就是当前读头，出栈顺序正好是剩余输入串的自然顺序
	string input = "";
	while (!input_s.empty()) {
		input += input_s.top();
		input_s.pop();
	}
	//推导步骤显示所用的产生式，匹配步骤右部为空、只显示被匹配掉的终结符
	string action = "";
	if (!rule_temp.right.empty()) {
		ostringstream text;
		text << rule_temp;
		action = text.str();
	}
	else if (rule_temp.left != ' ') {
		action = string("匹配") + rule_temp.left;
	}
	cout << left << setw(20) << analysis << setw(20) << input << setw(16) << action << endl;
	cout << right;
}
void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;

	//输入栈：栈底放输入串结束符“#”，待分析串逆序进栈，栈顶即当前读头
	stack<char> input_s;
	input_s.push('#');
	for (int i = (int)input.length() - 1; i >= 0; i--) {
		input_s.push(input[i]);
	}
	//分析栈：栈底同样放“#”，再压入文法开始符号，即行表头的第一个非终结符
	stack<char> analysis_s;
	analysis_s.push('#');
	if (!table.row.empty()) {
		analysis_s.push(table.row[0]);
	}
	//分析状态标志：一旦出现无法匹配或查不到产生式的情况就置为false
	bool success = true;
	int step = 1;

	//输出分析过程的表头
	cout << endl << "语法分析过程如下：" << endl;
	cout << left << setw(8) << "步骤" << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(16) << "所用产生式" << endl;
	cout << right;

	while (true) {
		char top = analysis_s.top();
		char head = input_s.top();
		rule rule_temp;
		rule_temp.left = ' ';//该步骤没有用到产生式时这一列留空

		if (top == '#') {
			//分析栈退到栈底：输入串同时读完则分析成功，否则输入串还有多余的符号
			cout << left << setw(8) << step;
			print_state(analysis_s, input_s, rule_temp);
			if (head != '#') {
				success = false;
				cout << "    出错：分析栈已空，输入串中还剩下符号“" << head << "”" << endl;
			}
			break;
		}
		if (index_of(table.row, top) < 0) {
			//栈顶是终结符：与当前输入符号相同则匹配掉，否则分析失败
			if (top != head) {
				success = false;
				cout << left << setw(8) << step;
				print_state(analysis_s, input_s, rule_temp);
				cout << "    出错：栈顶终结符“" << top << "”与当前输入符号“" << head << "”不匹配" << endl;
				break;
			}
			rule_temp.left = top;//匹配步骤只记录被匹配掉的终结符，右部保持为空
			cout << left << setw(8) << step;
			print_state(analysis_s, input_s, rule_temp);
			analysis_s.pop();
			input_s.pop();
			step++;
			continue;
		}
		//栈顶是非终结符：查分析表决定用哪一条产生式展开
		int r = index_of(table.row, top);
		int c = index_of(table.col, head);
		rule cell;
		cell.left = ' ';
		if (c >= 0) {
			cell = table.rules[r * table.col.size() + c];
		}
		if (cell.right.empty()) {
			success = false;
			cout << left << setw(8) << step;
			print_state(analysis_s, input_s, rule_temp);
			cout << "    出错：分析表中“" << top << "”行“" << head << "”列是空白单元格" << endl;
			break;
		}
		rule_temp = cell;
		cout << left << setw(8) << step;
		print_state(analysis_s, input_s, rule_temp);
		//用产生式右部替换掉栈顶的非终结符，右部逆序进栈，“@”代表空串不进栈
		analysis_s.pop();
		string right_part = cell.right[0];
		if (right_part != "@") {
			for (int k = (int)right_part.length() - 1; k >= 0; k--) {
				analysis_s.push(right_part[k]);
			}
		}
		step++;
		if (step > 1000) {
			//文法有环或者不满足LL(1)条件时可能一直展开下去，加一道保险
			success = false;
			cout << "    出错：分析步骤过多，分析过程无法结束" << endl;
			break;
		}
	}

	cout << endl << "字符串" << input;
	if (!success) {
		cout << "不";
	}
	cout << "是该文法的句子" << endl;
}
